contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Target that always rejects incoming calls/funds so the inner call fails.
    fallback() external payable {
        revert("target rejects");
    }

    function run(address target, uint value, bytes memory data) public payable {
        require(address(c).balance >= value, "c lacks funds");
        uint beforeTargetBalance = target.balance;
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // General rule: funds reach the target if and only if sendMoney succeeds.
        // If the inner call failed, P reverts (target balance unchanged); M swallows
        // the failure and completes without the target having received anything,
        // breaking the invariant.
        assert(address(target).balance == beforeTargetBalance + (reverted ? 0 : value));
    }
}

